@Override // com.macrovideo.v380.activities.BaseActivity
protected void onClicked(View view) {
    int id = view.getId();
    if (id == R.id.btn_left_common_top_bar) {
        onBackPressed();
        return;
    }
    if (id == R.id.tv_clear) {
        for (int i = 0; i < DeviceConfigSettingAlarmSettingFragment.sAlarmAreaRows * DeviceConfigSettingAlarmSettingFragment.sAlarmAreaColumns; i++) {
            this.mAlarmAreaList.remove(i);
            this.mAlarmAreaList.add(i, 0);
        }
        this.mAdapter.notifyDataSetChanged();
        changeSelectBtn();
        return;
    }
    if (id == R.id.tv_select_all) {
        if (this.isSelectedAll) {
            for (int i2 = 0; i2 < DeviceConfigSettingAlarmSettingFragment.sAlarmAreaRows * DeviceConfigSettingAlarmSettingFragment.sAlarmAreaColumns; i2++) {
                this.mAlarmAreaList.remove(i2);
                this.mAlarmAreaList.add(i2, 0);
            }
        } else {
            for (int i3 = 0; i3 < DeviceConfigSettingAlarmSettingFragment.sAlarmAreaRows * DeviceConfigSettingAlarmSettingFragment.sAlarmAreaColumns; i3++) {
                this.mAlarmAreaList.remove(i3);
                this.mAlarmAreaList.add(i3, 1);
            }
        }
        this.mAdapter.notifyDataSetChanged();
        changeSelectBtn();
        return;
    }
    if (id == R.id.tv_confirm) {
        saveAreaSelected();
    }
}
